using System.Text.Json;using Licentivo;
namespace LicentivoDemo;
static class Program{[STAThread]static void Main(){ApplicationConfiguration.Initialize();Application.Run(new DemoForm());}}
sealed class DemoForm:Form{
    readonly TextBox output=new(){Multiline=true,ReadOnly=true,Dock=DockStyle.Fill,ScrollBars=ScrollBars.Vertical},key=new(){Width=400,UseSystemPasswordChar=true};LicentivoClient? client;string? pendingID,pendingJob,configPath;bool busy;readonly CheckBox metered=new(){Text="Export has a usage limit",AutoSize=true};
    readonly Func<string?> chooseOutput;
    public DemoForm():this(ChooseReportPath){}
    internal DemoForm(Func<string?> outputSelector){chooseOutput=outputSelector;Text="Licentivo · Application example";Width=820;Height=460;var buttons=new FlowLayoutPanel{Dock=DockStyle.Top,Height=130,AutoSize=true};Controls.Add(output);Controls.Add(buttons);buttons.Controls.Add(new Label{Text="License key / transfer code (empty to restore)",AutoSize=true});buttons.Controls.Add(key);buttons.Controls.Add(metered);Add(buttons,"Choose product.json",()=>{using var dialog=new OpenFileDialog{Filter="Product settings|*.json"};if(dialog.ShowDialog()==DialogResult.OK){configPath=dialog.FileName;Log("Product settings selected.");}return Task.CompletedTask;});Add(buttons,"Activate / restore",async()=>{if(configPath is null)throw new InvalidOperationException("Select product.json first.");if(pendingID is not null)throw new InvalidOperationException("Finish the pending commit before changing the client.");var secret=key.Text;if(client is not null)await client.DisposeAsync();client=null;client=await LicentivoClient.OpenWithLicense(configPath,secret,e=>ShowLog(e.Message));client.StatusChanged+=s=>ShowLog(s.State);key.Clear();Log(client.Status().State);});Add(buttons,"Export a report",Export);Add(buttons,"Retry pending commit",Commit);Add(buttons,"Refresh",async()=>{await Require().RefreshOnline();Log(Require().Status().State);});Add(buttons,"Release device",async()=>{await Require().Deactivate();Log("Device released. Get a transfer code from the customer portal for a new machine.");});FormClosed+=async(_,_)=>{if(client is not null)await client.DisposeAsync();};}
    static string? ChooseReportPath(){using var dialog=new SaveFileDialog{FileName="licensed-report.txt",Filter="Text report|*.txt"};return dialog.ShowDialog()==DialogResult.OK?dialog.FileName:null;}
    void ShowLog(string text){if(IsDisposed)return;if(InvokeRequired){BeginInvoke((Action)(()=>ShowLog(text)));return;}Log(text);}
    async Task Commit(){if(pendingID is null)return;var receipt=await Require().Commit(pendingID,pendingJob!);pendingID=pendingJob=null;Log("Usage committed. Remaining: "+receipt.Consumption.Remaining);}
    async Task Export(){var c=Require();var state=c.FeatureStatus("export");if(!state.Allowed)throw new InvalidOperationException(state.Code==""?state.State:state.Code);if(pendingID is not null)throw new InvalidOperationException("Retry the pending commit before exporting again.");var filename=chooseOutput();if(filename is null)return;var job=Guid.NewGuid().ToString();var hold=metered.Checked?await c.Reserve("export",1,job):null;if(hold is not null&&hold.Status!="pending")throw new InvalidOperationException("Closed operation; do not export again.");try{await File.WriteAllTextAsync(filename,"A report generated by the licensed application.\n");}catch{if(hold is not null)await c.Cancel(hold.ReservationId,job);throw;}if(hold is not null){pendingID=hold.ReservationId;pendingJob=job;await Commit();}Log("Export completed: "+filename);}
    LicentivoClient Require()=>client??throw new InvalidOperationException("Load a configuration file first.");void Log(string s)=>output.AppendText(s+Environment.NewLine);
    void Add(Control root,string title,Func<Task> action){var b=new Button{Text=title,AutoSize=true};b.Click+=async(_,_)=>{if(busy)return;busy=true;root.Enabled=false;try{await action();}catch(Exception e){ShowLog(e.Message);}finally{busy=false;if(!IsDisposed)root.Enabled=true;}};root.Controls.Add(b);}
}
